# This code is an example that can be run through the qmd file, not the html

library(shiny)
library(ggplot2)
library(dplyr)

ui &lt;- fluidPage(
  titlePanel("Sample Shiny App: Car MPG Explorer"),

  sidebarLayout(
    sidebarPanel(
      selectInput(
        inputId = "cylinders",
        label = "Choose number of cylinders:",
        choices = sort(unique(mtcars$cyl)),
        selected = 4
      )
    ),

    mainPanel(
      plotOutput("mpgPlot"),
      tableOutput("summaryTable")
    )
  )
)

server &lt;- function(input, output, session) {

  filtered_data &lt;- reactive({
    mtcars |&gt;
      filter(cyl == input$cylinders)
  })

  output$mpgPlot &lt;- renderPlot({
    ggplot(filtered_data(), aes(x = wt, y = mpg)) +
      geom_point(size = 3) +
      labs(
        title = paste("MPG vs Weight for", input$cylinders, "Cylinder Cars"),
        x = "Weight",
        y = "Miles Per Gallon"
      ) +
      theme_minimal()
  })

  output$summaryTable &lt;- renderTable({
    filtered_data() |&gt;
      summarise(
        Average_MPG = round(mean(mpg), 2),
        Average_Weight = round(mean(wt), 2),
        Number_of_Cars = n()
      )
  })
}

shinyApp(ui = ui, server = server)
